//! The write guard of Cart (generated by metaphor-schema; do not edit). It lives in a
//! file of its own because `cart_service.rs` is hand-owned.

#[allow(unused_imports)]
use super::*;
use crate::domain::entity::Cart;

/// The rules the schema declares for Cart, checked against the row a create or update
/// would store. The generated build attaches it to [`CartService`]. A refusing rule's
/// break answers 422; a rule in shadow is logged under `backbone::write_guard` and the
/// write goes ahead.
pub struct CartRowRules;

#[async_trait::async_trait]
impl backbone_core::write_guard::WriteGuard<Cart> for CartRowRules {
    async fn check(
        &self,
        ctx: &backbone_core::write_guard::WriteCtx<'_, Cart>,
    ) -> backbone_core::write_guard::GuardOutcome {
        use backbone_core::row_rule as r;
        use backbone_core::violation::Violation;
        use backbone_core::write_guard::{GuardOutcome, WriteKind};
        let (create, update) = (ctx.kind == WriteKind::Create, ctx.kind == WriteKind::Update);
        let Some(after) = ctx.after.filter(|_| create || update) else {
            return GuardOutcome::allow();
        };
        let Ok(row) = serde_json::to_value(after) else {
            return GuardOutcome::allow();
        };
        let row = &row;
        let old = ctx.before.and_then(|b| serde_json::to_value(b).ok());
        let mut shadow = Vec::new();
        let mut refuse = Vec::new();
        // `website_id_required` (@required on Cart.website_id)
        if (create || (update && r::changed(old.as_ref(), row, &["website_id"]))) && !r::holds(&r::and(r::is_not_null(r::field(row, "website_id")), r::not(r::is_empty(r::trim(r::field(row, "website_id")))))) {
            refuse.push(Violation::new("website_id", "required", "website_id is required"));
        }
        // `visitor_id_required` (@required on Cart.visitor_id)
        if (create || (update && r::changed(old.as_ref(), row, &["visitor_id"]))) && !r::holds(&r::and(r::is_not_null(r::field(row, "visitor_id")), r::not(r::is_empty(r::trim(r::field(row, "visitor_id")))))) {
            refuse.push(Violation::new("visitor_id", "required", "visitor_id is required"));
        }
        // `coupon_code_max_length` (@max(60) on Cart.coupon_code)
        if (create || (update && r::changed(old.as_ref(), row, &["coupon_code"]))) && !r::holds(&r::le(r::length(r::field(row, "coupon_code")), r::Val::Num(60.0_f64))) {
            shadow.push(Violation::new("coupon_code", "max_length", "coupon_code must be at most 60 characters").with_param("max", 60_i64));
        }
        // `fulfillment_mode_max_length` (@max(20) on Cart.fulfillment_mode)
        if (create || (update && r::changed(old.as_ref(), row, &["fulfillment_mode"]))) && !r::holds(&r::le(r::length(r::field(row, "fulfillment_mode")), r::Val::Num(20.0_f64))) {
            shadow.push(Violation::new("fulfillment_mode", "max_length", "fulfillment_mode must be at most 20 characters").with_param("max", 20_i64));
        }
        GuardOutcome { refuse, shadow }
    }
}
